import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Design tokens
  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const typeScale = {
    headline: 0.34
  };

  // Extract configuration
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  const text = config.textContent?.text || 'Collection 3';
  const textRole = config.textContent?.role || 'headline';

  // Create plane geometry (512x320 px = 1.6:1 aspect)
  const planeGeometry = new THREE.PlaneGeometry(1.6, 1);

  // Load texture
  const texture = ctx.textureLoader.load(imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create material
  const material = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true
  });

  // Create and configure card mesh
  const cardMesh = new THREE.Mesh(planeGeometry, material);
  cardMesh.position.set(
    config.scenePosition?.x ?? 3.2,
    config.scenePosition?.y ?? 1,
    config.scenePosition?.z ?? 0.06
  );
  cardMesh.rotation.set(
    config.rotation?.x ?? 0,
    config.rotation?.y ?? 0,
    config.rotation?.z ?? 0
  );
  cardMesh.scale.set(
    config.scale?.x ?? 1,
    config.scale?.y ?? 1,
    config.scale?.z ?? 1
  );

  group.add(cardMesh);

  // Render text using fontAtlas
  if (ctx.fontAtlas) {
    const fontSize = typeScale[textRole] || typeScale.headline;
    const textMesh = ctx.fontAtlas.createTextMesh(text, {
      fontSize,
      fontFamily: 'Lora',
      fontWeight: 400,
      color: colors.ink,
      anchor: 'center'
    });

    if (textMesh) {
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // Apply cinematic primitives if any
  if (config.cinematicPrimitives?.length > 0) {
    config.cinematicPrimitives.forEach(primitive => {
      if (ctx.primitives?.[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params);
      }
    });
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    material.dispose();
    texture.dispose();
    gsap.killTweensOf(group);
  };

  group.userData.handlers = {};

  return group;
}
